/**                                                                       */
/** ThreadX Test                                                          */
/**                                                                       */
/**   Module Manager thread control ownership                             */
/**                                                                       */
/**************************************************************************/
/**************************************************************************/

/* A memory-protected module names a thread when it asks the Module Manager to
   suspend, resume, terminate or reset it, to change its priority, preemption
   threshold or time slice, or to abort its wait. Authenticating the pointer only
   establishes that it is a live thread outside the module, which every application
   thread and every other module's thread is. The dispatchers must also establish
   that the thread belongs to the calling module, as tx_thread_entry_exit_notify
   already does, or one module controls the execution of every other thread.

   The test drives each of the eight dispatchers with three threads on the kernel's
   created list: one owned by the calling module, one owned by another module, and
   one created by the application. A protected caller must reach the kernel service
   for its own thread only, and be refused with TXM_MODULE_INVALID for the other two
   without the service being reached. A caller without memory protection is not
   isolated and must reach the service for every thread, as before. The build
   defines every dispatch guard except the eight under test.  */

#include <stdio.h>
#include <string.h>

#include "threadx_module_manager_host_test_port.h"

#include "tx_thread.h"
#include "tx_timer.h"
#include "tx_queue.h"
#include "tx_event_flags.h"
#include "tx_semaphore.h"
#include "tx_mutex.h"
#include "tx_block_pool.h"
#include "tx_byte_pool.h"
#include "txm_module.h"
#include "txm_module_manager_util.h"
#include "txm_module_manager_dispatch.h"

#if defined(TXM_THREAD_SUSPEND_CALL_NOT_USED) || defined(TXM_THREAD_RESUME_CALL_NOT_USED) || \
    defined(TXM_THREAD_TERMINATE_CALL_NOT_USED) || defined(TXM_THREAD_RESET_CALL_NOT_USED) || \
    defined(TXM_THREAD_PRIORITY_CHANGE_CALL_NOT_USED) || defined(TXM_THREAD_PREEMPTION_CHANGE_CALL_NOT_USED) || \
    defined(TXM_THREAD_TIME_SLICE_CHANGE_CALL_NOT_USED) || defined(TXM_THREAD_WAIT_ABORT_CALL_NOT_USED)
#error "the thread control services under test must be compiled in"
#endif

#ifndef TXM_THREAD_DELETE_CALL_NOT_USED
#error "the services this test does not exercise must be compiled out"
#endif


/* Interrupt lock accounting, referenced by the force-included port shim.  */
unsigned int    test_interrupt_disable_depth;
unsigned int    test_interrupt_disable_max_depth;
unsigned int    test_interrupt_restore_underflows;

/* The kernel's created lists. Only the thread list is populated, by the three
   threads below; the others stay empty because nothing here creates such objects.  */
TX_BLOCK_POOL           *_tx_block_pool_created_ptr;
ULONG                   _tx_block_pool_created_count;
TX_BYTE_POOL            *_tx_byte_pool_created_ptr;
ULONG                   _tx_byte_pool_created_count;
TX_EVENT_FLAGS_GROUP    *_tx_event_flags_created_ptr;
ULONG                   _tx_event_flags_created_count;
TX_MUTEX                *_tx_mutex_created_ptr;
ULONG                   _tx_mutex_created_count;
TX_QUEUE                *_tx_queue_created_ptr;
ULONG                   _tx_queue_created_count;
TX_SEMAPHORE            *_tx_semaphore_created_ptr;
ULONG                   _tx_semaphore_created_count;
TX_THREAD               *_tx_thread_created_ptr;
ULONG                   _tx_thread_created_count;
TX_TIMER                *_tx_timer_created_ptr;
ULONG                   _tx_timer_created_count;

/* The manager globals the utility source refers to.  */
TX_BYTE_POOL    _txm_module_manager_object_pool;
UINT            _txm_module_manager_object_pool_created;


static UINT     test_failures;
static ULONG    test_checks;


/* Record the outcome of one expectation.  */
static VOID  test_expect(const char *description, ULONG actual, ULONG expected)
{
    test_checks++;

    if (actual != expected)
    {
        printf("FAIL: %s (expected %lu, got %lu)\n", description, (unsigned long) expected, (unsigned long) actual);
        test_failures++;
    }
}


/* No module data is modelled, so every range lies outside the calling module.  */
UINT  _txm_module_manager_inside_data_check(TXM_MODULE_INSTANCE *module_instance, ALIGN_TYPE obj_ptr,
                                            ULONG obj_size, UINT write_request)
{
    (VOID) module_instance;
    (VOID) obj_ptr;
    (VOID) obj_size;
    (VOID) write_request;

    return(TX_FALSE);
}

UINT  _txm_module_manager_outside_data_check(TXM_MODULE_INSTANCE *module_instance, ALIGN_TYPE obj_ptr,
                                             ULONG obj_size)
{
    (VOID) module_instance;
    (VOID) obj_ptr;
    (VOID) obj_size;

    return(TX_TRUE);
}

/* Referenced by a loading path in the utility source that this test never reaches.  */
VOID  _txm_module_manager_alignment_adjust(TXM_MODULE_PREAMBLE *module_preamble, ULONG *code_size,
                                           ULONG *code_alignment, ULONG *data_size, ULONG *data_alignment)
{
    (VOID) module_preamble;
    (VOID) code_size;
    (VOID) code_alignment;
    (VOID) data_size;
    (VOID) data_alignment;
}


/* Stand in for the kernel services, recording which thread each was handed.  */
static ULONG        test_service_calls;
static TX_THREAD    *test_service_thread;

static UINT  test_service(TX_THREAD *thread_ptr)
{
    test_service_calls++;
    test_service_thread =  thread_ptr;

    return(TX_SUCCESS);
}

UINT  _txe_thread_suspend(TX_THREAD *thread_ptr)
{
    return(test_service(thread_ptr));
}

UINT  _txe_thread_resume(TX_THREAD *thread_ptr)
{
    return(test_service(thread_ptr));
}

UINT  _txe_thread_terminate(TX_THREAD *thread_ptr)
{
    return(test_service(thread_ptr));
}

UINT  _txm_module_manager_thread_reset(TX_THREAD *thread_ptr)
{
    return(test_service(thread_ptr));
}

UINT  _txe_thread_wait_abort(TX_THREAD *thread_ptr)
{
    return(test_service(thread_ptr));
}

UINT  _txe_thread_priority_change(TX_THREAD *thread_ptr, UINT new_priority, UINT *old_priority)
{
    (VOID) new_priority;
    (VOID) old_priority;

    return(test_service(thread_ptr));
}

UINT  _txe_thread_preemption_change(TX_THREAD *thread_ptr, UINT new_threshold, UINT *old_threshold)
{
    (VOID) new_threshold;
    (VOID) old_threshold;

    return(test_service(thread_ptr));
}

UINT  _txe_thread_time_slice_change(TX_THREAD *thread_ptr, ULONG new_time_slice, ULONG *old_time_slice)
{
    (VOID) new_time_slice;
    (VOID) old_time_slice;

    return(test_service(thread_ptr));
}


/* Call one of the eight dispatchers on a thread. The priority, threshold and time
   slice requests ask for a value every module may set, and pass no old-value
   buffer, so only the thread decides the outcome.  */
#define TEST_SERVICE_COUNT  ((UINT) 8)

static const char * const   test_service_names[TEST_SERVICE_COUNT] =
{
    "suspend", "resume", "terminate", "reset",
    "priority change", "preemption change", "time slice change", "wait abort"
};

static ALIGN_TYPE  test_dispatch(UINT service, TXM_MODULE_INSTANCE *module_instance, TX_THREAD *thread_ptr)
{

ALIGN_TYPE  thread_param;
ALIGN_TYPE  return_value;

    thread_param =  (ALIGN_TYPE) thread_ptr;

    switch (service)
    {
    case 0U:
        return_value =  _txm_module_manager_tx_thread_suspend_dispatch(module_instance, thread_param);
        break;
    case 1U:
        return_value =  _txm_module_manager_tx_thread_resume_dispatch(module_instance, thread_param);
        break;
    case 2U:
        return_value =  _txm_module_manager_tx_thread_terminate_dispatch(module_instance, thread_param);
        break;
    case 3U:
        return_value =  _txm_module_manager_tx_thread_reset_dispatch(module_instance, thread_param);
        break;
    case 4U:
        return_value =  _txm_module_manager_tx_thread_priority_change_dispatch(module_instance, thread_param, (ALIGN_TYPE) 16, (ALIGN_TYPE) 0);
        break;
    case 5U:
        return_value =  _txm_module_manager_tx_thread_preemption_change_dispatch(module_instance, thread_param, (ALIGN_TYPE) 16, (ALIGN_TYPE) 0);
        break;
    case 6U:
        return_value =  _txm_module_manager_tx_thread_time_slice_change_dispatch(module_instance, thread_param, (ALIGN_TYPE) 4, (ALIGN_TYPE) 0);
        break;
    default:
        return_value =  _txm_module_manager_tx_thread_wait_abort_dispatch(module_instance, thread_param);
        break;
    }

    return(return_value);
}


/* The calling module, another module, and the threads the requests name.  */
static TXM_MODULE_INSTANCE  test_caller;
static TXM_MODULE_INSTANCE  test_other_module;
static TX_THREAD            test_own_thread;
static TX_THREAD            test_other_thread;
static TX_THREAD            test_application_thread;


/* Put the three threads on the kernel's created list, as created threads are.  */
static VOID  test_threads_create(VOID)
{
    memset((VOID *) &test_own_thread, 0, sizeof(TX_THREAD));
    memset((VOID *) &test_other_thread, 0, sizeof(TX_THREAD));
    memset((VOID *) &test_application_thread, 0, sizeof(TX_THREAD));

    test_own_thread.tx_thread_id =                       TX_THREAD_ID;
    test_own_thread.tx_thread_module_instance_ptr =      (VOID *) &test_caller;
    test_other_thread.tx_thread_id =                     TX_THREAD_ID;
    test_other_thread.tx_thread_module_instance_ptr =    (VOID *) &test_other_module;
    test_application_thread.tx_thread_id =               TX_THREAD_ID;
    test_application_thread.tx_thread_module_instance_ptr =  TX_NULL;

    test_own_thread.tx_thread_created_next =             &test_other_thread;
    test_other_thread.tx_thread_created_next =           &test_application_thread;
    test_application_thread.tx_thread_created_next =     &test_own_thread;
    test_own_thread.tx_thread_created_previous =         &test_application_thread;
    test_other_thread.tx_thread_created_previous =       &test_own_thread;
    test_application_thread.tx_thread_created_previous = &test_other_thread;

    _tx_thread_created_ptr =    &test_own_thread;
    _tx_thread_created_count =  (ULONG) 3;
}


int  main(void)
{

UINT        service;
UINT        protected_caller;
ALIGN_TYPE  return_value;
char        description[160];

    test_threads_create();

    for (protected_caller = 0U; protected_caller < 2U; protected_caller++)
    {
        memset((VOID *) &test_caller, 0, sizeof(test_caller));
        memset((VOID *) &test_other_module, 0, sizeof(test_other_module));
        test_caller.txm_module_instance_property_flags =  (protected_caller != 0U) ?
            (ULONG) (TXM_MODULE_USER_MODE | TXM_MODULE_MEMORY_PROTECTION) : (ULONG) 0;

        for (service = 0U; service < TEST_SERVICE_COUNT; service++)
        {

            /* The caller's own thread reaches the service whether or not the caller
               is protected.  */
            test_service_calls =   0U;
            test_service_thread =  TX_NULL;
            return_value =  test_dispatch(service, &test_caller, &test_own_thread);
            snprintf(description, sizeof(description), "a %s module's %s of its own thread reaches the service",
                     (protected_caller != 0U) ? "protected" : "unprotected", test_service_names[service]);
            test_expect(description, test_service_calls, (ULONG) 1);
            test_expect("...for that thread", (ULONG) (test_service_thread == &test_own_thread), (ULONG) TX_TRUE);
            test_expect("...and returns the service's status", (ULONG) return_value, (ULONG) TX_SUCCESS);

            /* Another module's thread and an application thread are refused for a
               protected caller, and reach the service for an unprotected one.  */
            test_service_calls =  0U;
            return_value =  test_dispatch(service, &test_caller, &test_other_thread);
            snprintf(description, sizeof(description), "a %s module's %s of another module's thread",
                     (protected_caller != 0U) ? "protected" : "unprotected", test_service_names[service]);
            test_expect(description, (ULONG) return_value,
                        (protected_caller != 0U) ? (ULONG) TXM_MODULE_INVALID : (ULONG) TX_SUCCESS);
            test_expect("...reaches the service only when the caller is unprotected", test_service_calls,
                        (protected_caller != 0U) ? (ULONG) 0 : (ULONG) 1);

            test_service_calls =  0U;
            return_value =  test_dispatch(service, &test_caller, &test_application_thread);
            snprintf(description, sizeof(description), "a %s module's %s of an application thread",
                     (protected_caller != 0U) ? "protected" : "unprotected", test_service_names[service]);
            test_expect(description, (ULONG) return_value,
                        (protected_caller != 0U) ? (ULONG) TXM_MODULE_INVALID : (ULONG) TX_SUCCESS);
            test_expect("...reaches the service only when the caller is unprotected", test_service_calls,
                        (protected_caller != 0U) ? (ULONG) 0 : (ULONG) 1);
        }
    }

    /* Nothing on these paths disables interrupts, and the shim counts them.  */
    test_expect("the interrupt lock is balanced", (ULONG) test_interrupt_disable_depth, (ULONG) 0);
    test_expect("the interrupt lock never underflowed", (ULONG) test_interrupt_restore_underflows, (ULONG) 0);

    test_expect("every case ran", test_checks, (ULONG) 114);

    if (test_failures == 0U)
    {
        printf("SUCCESS! %lu expectations\n", (unsigned long) test_checks);
        return(0);
    }

    printf("ERROR: %u expectation(s) failed of %lu\n", test_failures, (unsigned long) test_checks);
    return(1);
}
